for bi, (ename, theme, note, titles) in enumerate(BATCHES):
    assert len(titles) == 20, ename
    f1 = bi * 20 + 1
    f2 = f1 + 19
    lines = []
    lines.append(f"#### UNX-E4-{ename} · {theme}（UNX-E4-E{f1:03d}–E{f2:03d} · 20 条）")
    lines.append("")
    lines.append(f"> AI-24 承办｜增补卷一（独立编号不占域账，判例承 AI-29/AI-15/AI-19 D4 增补卷判例）｜域账累计：不占（增补卷独立计量，F19189 封账宣示不破）｜嫁接源：E4 域 B01–B40 全部产物为承接契约；域内互证挂点见各条判据｜防重：与 B01–B40 分层——本批管「{note[:36]}」；主题聚类对全域判据对表嫌疑=空｜批注：{note}｜状态列统一「增补」不冒充深化｜红线声明：涉写盘条目一律三重验证+dry-run+原子写；无引导类条目")
    lines.append("")
    lines.append("| 编号 | 功能条目 | 行数 | 状态 | 判据 |")
    lines.append("|---|---|---|---|---|")
    for i, title in enumerate(titles):
        fid = f1 + i
        eid = f"UNX-E4-E{fid:03d}"
        crit = f"{eid}-J1 " + cr(title, i % 5)
        lines.append(f"| {eid} | {title} | {ROW_PATTERN[i]} | 增补 | {crit} |")
    io.open(os.path.join(OUT, f"UNX-E4-{ename}.md"), "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    print(f"{ename} OK: E{f1:03d}-E{f2:03d} 20 条 / 6,000 行")
